 */

/** Thrown while reading the sheet text; carries the failing line number. */
export class SheetError extends Error {
  constructor(message) {
    super(message)
    this.name = 'SheetError'
  }
}

/** Thrown by the tokenizer/parser when a formula body does not fit the grammar. */
export class GrammarError extends Error {
  constructor() {
    super('grammar error')
    this.name = 'GrammarError'
  }
}

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
"}

