{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/address.js","content":"/**
 * Cell address helpers: column/row encoding and the addressable-range check.
 *
 * Columns run `A`..`Z` then `AA`..`ZZ` (1 or 2 letters only). A column's
 * index is its value in that ordering, starting at 1, computed by reading
 * its letters as base-26 digits (`A`=1 .. `Z`=26).
 */

/** Converts uppercase column letters ("A".."ZZ") to their 1-based index. */
export function colIndex(letters) {
  let index = 0
  for (const ch of letters) index = index * 26 + (ch.charCodeAt(0) - 64)
  return index
}

/** Converts a 1-based column index back to its uppercase letters. */
export function colLetters(index) {
  if (index <= 26) return String.fromCharCode(64 + index)
  const rest = index - 26
  const first = Math.floor((rest - 1) / 26) + 1
  const second = ((rest - 1) % 26) + 1
  return String.fromCharCode(64 + first) + String.fromCharCode(64 + second)
}

/**
 * Classifies a letters+digits pair. Valid addresses are 1-2 letters and
 * 1-3 digits naming a row of at least 1; anything else is "outside the
 * addressable range" (still a syntactically fine word, just not a cell).
 */
export function classifyAddress(letters, digits) {
  if (letters.length < 1 || letters.length > 2) return { valid: false }
  if (digits.length < 1 || digits.length > 3) return { valid: false }
  const row = parseInt(digits, 10)
  if (row < 1) return { valid: false }
  const up = letters.toUpperCase()
  const col = colIndex(up)
  return { valid: true, col, row, canonical: up + String(row) }
}

/** Splits a canonical address ("A1", "AZ12") back into its col/row indexes. */
export function splitCanonical(addr) {
  const m = /^([A-Z]{1,2})([0-9]+)$/.exec(addr)
  return { col: colIndex(m[1]), row: Number(m[2]) }
}

/** Ascending column, then ascending row, ordering used for printing cells. */
export function compareAddresses(a, b) {
  const pa = splitCanonical(a)
  const pb = splitCanonical(b)
  if (pa.col !== pb.col) return pa.col - pb.col
  return pa.row - pb.row
}
"}

