{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/tokenizer.js","content":"/**
 * Tokenizer for formula bodies (the text after the leading `=`).
 */

import { GrammarError } from './errors.js'

const NUMBER_RE = /^[0-9]+(\.[0-9]+)?/
const WORD_RE = /^[A-Za-z]+[0-9]*/

/** Splits a formula body into a flat token list, or throws GrammarError. */
export function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const c = body[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    if ('^*/+-'.includes(c)) {
      tokens.push({ type: 'OP', op: c })
      i++
      continue
    }
    if (c === '=') {
      tokens.push({ type: 'OP', op: '=' })
      i++
      continue
    }
    if (c === '<') {
      if (body[i + 1] === '>') {
        tokens.push({ type: 'OP', op: '<>' })
        i += 2
      } else if (body[i + 1] === '=') {
        tokens.push({ type: 'OP', op: '<=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', op: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'OP', op: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', op: '>' })
        i++
      }
      continue
    }
    if (/[0-9]/.test(c)) {
      const m = NUMBER_RE.exec(body.slice(i))
      tokens.push({ type: 'NUMBER', value: m[0] })
      i += m[0].length
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      const m = WORD_RE.exec(body.slice(i))
      tokens.push({ type: 'WORD', value: m[0] })
      i += m[0].length
      continue
    }
    throw new GrammarError()
  }
  return tokens
}
"}

