 * Parses sheet text into a Map from canonical address to declared content.
 */

import { SheetError } from './errors.js'

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/**
 * @param {string} text raw stdin contents
 * @returns {Map<string, {content: string, col: number, row: number}>}
 */
export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const raw = lines[i]
    const stripped = raw.replace(/^[ \t]+/, '')
    if (stripped === '' || stripped[0] === '#') continue

    let idx = 0
    while (idx < stripped.length && stripped[idx] !== ' ' && stripped[idx] !== '\t') idx++
    const addrToken = stripped.slice(0, idx)
    let j = idx
    while (j < stripped.length && (stripped[j] === ' ' || stripped[j] === '\t')) j++
    const content = stripped.slice(j)

    const m = ADDRESS_RE.exec(addrToken)
    const row = m ? parseInt(m[2], 10) : 0
    if (!m || row < 1) {
      throw new SheetError(`line ${lineNo}: invalid cell address ${addrToken}`)
    }
    const letters = m[1].toUpperCase()
    const canonical = letters + String(row)
    if (cells.has(canonical)) {
      throw new SheetError(`line ${lineNo}: cell ${canonical} is declared twice`)
    }
    cells.set(canonical, { content, letters, row })
  }
  return cells
}
"}

