 * Formats evaluated cell values for the `values` output mode.
 */

/** Rounds to 10 significant digits, then formats the way JS would. */
export function formatNumber(n) {
  if (n === 0) return '0'
  const rounded = Number(n.toPrecision(10))
  return String(rounded)
}

export function formatValue(value) {
  switch (value.type) {
    case 'number':
      return formatNumber(value.value)
    case 'boolean':
      return value.value ? 'TRUE' : 'FALSE'
    case 'error':
      return value.value
    case 'text':
      return value.value
    default:
      throw new Error(`unknown value type ${value.type}`)
  }
}
"}

