 * Builds cell records (literal values or parsed formula ASTs) from the
 * addresses and raw content produced by parse-sheet.js.
 */

import { parseFormula } from './parser.js'
import { GrammarError, ERROR_TOKENS } from './errors.js'

const NUMBER_RE = /^-?[0-9]+(\.[0-9]+)?$/

function classifyLiteral(content) {
  if (content === '') return { type: 'number', value: 0 }
  if (ERROR_TOKENS.includes(content)) return { type: 'error', value: content }
  if (NUMBER_RE.test(content)) return { type: 'number', value: Number(content) }
  return { type: 'text', value: content }
}

/**
 * @param {Map<string, {content: string}>} sheet as produced by parseSheet
 * @returns {Map<string, object>} canonical address -> cell record
 */
export function buildModel(sheet) {
  const model = new Map()
  for (const [canonical, { content, letters, row }] of sheet) {
    if (content.startsWith('=')) {
      try {
        const ast = parseFormula(content.slice(1))
        model.set(canonical, { kind: 'formula', ast, letters, row })
      } catch (err) {
        if (!(err instanceof GrammarError)) throw err
        model.set(canonical, { kind: 'formula', ast: null, letters, row })
      }
    } else {
      model.set(canonical, { kind: 'literal', value: classifyLiteral(content), letters, row })
    }
  }
  return model
}
"}

