{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/deps.js","content":"/**
 * Structural dependency extraction: every address a formula's AST names,
 * ranges expanded, regardless of how (or whether) the formula evaluates.
 */

import { classifyAddress, colLetters, compareAddresses } from './address.js'

function addRange(set, rangeNode) {
  const ca = classifyAddress(rangeNode.a.letters, rangeNode.a.digits)
  const cb = classifyAddress(rangeNode.b.letters, rangeNode.b.digits)
  if (!ca.valid || !cb.valid) return
  const minCol = Math.min(ca.col, cb.col)
  const maxCol = Math.max(ca.col, cb.col)
  const minRow = Math.min(ca.row, cb.row)
  const maxRow = Math.max(ca.row, cb.row)
  for (let c = minCol; c <= maxCol; c++) {
    for (let r = minRow; r <= maxRow; r++) {
      set.add(colLetters(c) + r)
    }
  }
}

function walk(node, set) {
  if (!node) return
  switch (node.type) {
    case 'num':
    case 'bool':
      return
    case 'addr': {
      const cls = classifyAddress(node.letters, node.digits)
      if (cls.valid) set.add(cls.canonical)
      return
    }
    case 'range':
      addRange(set, node)
      return
    case 'paren':
      walk(node.inner, set)
      return
    case 'un':
      walk(node.operand, set)
      return
    case 'bin':
      walk(node.left, set)
      walk(node.right, set)
      return
    case 'call':
      for (const arg of node.args) walk(arg, set)
      return
    default:
      throw new Error(`unknown node type ${node.type}`)
  }
}

/** Returns the sorted, deduplicated list of addresses a formula AST names. */
export function collectDeps(ast) {
  const set = new Set()
  walk(ast, set)
  return [...set].sort(compareAddresses)
}
"}

