{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-WMYi1O/src/evaluate.js","content":"/**
 * Evaluates cell values.
 *
 * Cycle detection falls out of ordinary recursive evaluation: a "visiting"
 * set tracks the cells currently on the call stack, and looking up a cell
 * that is already visiting yields `#CYCLE!` for that lookup. Because
 * `#CYCLE!` is just another error value, it propagates through operators
 * and functions the same way any other error does.
 */

import { classifyAddress, colLetters } from './address.js'

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

const NUM = (value) => ({ type: 'number', value })
const BOOL = (value) => ({ type: 'boolean', value })
const ERR = (value) => ({ type: 'error', value })

function toNumber(v) {
  if (v.type === 'number') return v
  if (v.type === 'boolean') return NUM(v.value ? 1 : 0)
  if (v.type === 'error') return v
  return ERR('#VALUE!')
}

function finite(n) {
  return Number.isFinite(n) ? NUM(n) : ERR('#DIV/0!')
}

function rank(v) {
  if (v.type === 'number') return 0
  if (v.type === 'text') return 1
  return 2 // boolean
}

function compareValues(l, r) {
  const rl = rank(l)
  const rr = rank(r)
  if (rl !== rr) return rl < rr ? -1 : 1
  if (l.type === 'number') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  if (l.type === 'text') return l.value < r.value ? -1 : l.value > r.value ? 1 : 0
  const lv = l.value ? 1 : 0
  const rv = r.value ? 1 : 0
  return lv < rv ? -1 : lv > rv ? 1 : 0
}

/**
 * Reads a list of values as numbers, left to right; the first error (raw
 * or produced by a text-to-number conversion) wins.
 */
function toNumbersOrError(values) {
  const numbers = []
  for (const v of values) {
    if (v.type === 'error') return { error: v }
    const n = toNumber(v)
    if (n.type === 'error') return { error: n }
    numbers.push(n.value)
  }
  return { numbers }
}

function firstErrorOrFirst(values) {
  const err = values.find((v) => v.type === 'error')
  if (err) return err
  return values[0] ?? ERR('#REF!')
}

const CALL_SPECS = {
  SUM: { checkArgs: (n) => n >= 1 },
  MIN: { checkArgs: (n) => n >= 1 },
  MAX: { checkArgs: (n) => n >= 1 },
  COUNT: { checkArgs: (n) => n >= 1 },
  AVG: { checkArgs: (n) => n >= 1 },
  ABS: { checkArgs: (n) => n === 1 },
  IF: { checkArgs: (n) => n === 3 },
}

export function createEvaluator(model) {
  const cache = new Map()
  const visiting = new Set()

