      cache.set(canonical, v)
      return v
    }
    visiting.add(canonical)
    let v
    if (rec.kind === 'literal') {
      v = rec.value
    } else if (!rec.ast) {
      v = ERR('#ERR!')
    } else {
      v = evalNode(rec.ast)
    }
    visiting.delete(canonical)
    cache.set(canonical, v)
    return v
  }

  function flattenRange(node) {
    const ca = classifyAddress(node.a.letters, node.a.digits)
    const cb = classifyAddress(node.b.letters, node.b.digits)
    if (!ca.valid || !cb.valid) return [ERR('#REF!')]
    const minCol = Math.min(ca.col, cb.col)
    const maxCol = Math.max(ca.col, cb.col)
    const minRow = Math.min(ca.row, cb.row)
    const maxRow = Math.max(ca.row, cb.row)
    const out = []
    for (let c = minCol; c <= maxCol; c++) {
      for (let r = minRow; r <= maxRow; r++) out.push(getCellValue(colLetters(c) + r))
    }
    return out
  }

  function flattenArg(node) {
    if (node.type === 'range') return flattenRange(node)
    return [evalNode(node)]
  }

  function evalNode(node) {
    switch (node.type) {
      case 'num':
        return NUM(node.value)
      case 'bool':
        return BOOL(node.value)
      case 'paren':
        return evalNode(node.inner)
      case 'range':
        // A range not used directly as a function argument is a grammar
        // corner the language accepts syntactically but always errors on.
        return ERR('#ERR!')
      case 'addr': {
        const cls = classifyAddress(node.letters, node.digits)
        if (!cls.valid) return ERR('#REF!')
        return getCellValue(cls.canonical)
      }
      case 'un': {
        const v = evalNode(node.operand)
        if (v.type === 'error') return v
        const n = toNumber(v)
        if (n.type === 'error') return n
        return finite(node.op === '-' ? -n.value : n.value)
      }
      case 'bin':
        return evalBin(node)
      case 'call':
        return evalCall(node)
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalBin(node) {
    const l = evalNode(node.left)
    if (l.type === 'error') return l
    const r = evalNode(node.right)
    if (r.type === 'error') return r
    if (COMPARISON_OPS.has(node.op)) {
      const c = compareValues(l, r)
      switch (node.op) {
        case '=':
          return BOOL(c === 0)
        case '<>':
          return BOOL(c !== 0)
        case '<':
          return BOOL(c < 0)
        case '<=':
          return BOOL(c <= 0)
        case '>':
          return BOOL(c > 0)
        case '>=':
          return BOOL(c >= 0)
      }
    }
    const ln = toNumber(l)
    if (ln.type === 'error') return ln
    const rn = toNumber(r)
    if (rn.type === 'error') return rn
    switch (node.op) {
      case '+':
        return finite(ln.value + rn.value)
      case '-':
        return finite(ln.value - rn.value)
      case '*':
        return finite(ln.value * rn.value)
      case '/':
        return finite(ln.value / rn.value)
      case '^':
        return finite(Math.pow(ln.value, rn.value))
    }
    throw new Error(`unknown operator ${node.op}`)
  }

  function evalCall(node) {
    const name = node.name.toUpperCase()
    const spec = CALL_SPECS[name]
    if (!spec) return ERR('#NAME?')
    if (!spec.checkArgs(node.args.length)) return ERR('#ERR!')

    if (name === 'IF') {
      const cond = firstErrorOrFirst(flattenArg(node.args[0]))
      if (cond.type === 'error') return cond
      let truthy
      if (cond.type === 'boolean') truthy = cond.value
      else if (cond.type === 'number') truthy = cond.value !== 0
      else return ERR('#VALUE!')
      const branch = truthy ? node.args[1] : node.args[2]
      return firstErrorOrFirst(flattenArg(branch))
    }

    const values = node.args.flatMap(flattenArg)

    if (name === 'COUNT') {
      const err = values.find((v) => v.type === 'error')
      if (err) return err
      return NUM(values.filter((v) => v.type === 'number').length)
    }

    if (name === 'ABS') {
      const { error, numbers } = toNumbersOrError(values)
      if (error) return error
      return finite(Math.abs(numbers[0]))
    }

    const { error, numbers } = toNumbersOrError(values)
    if (error) return error
    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((a, b) => a + b, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((a, b) => a + b, 0) / numbers.length)
    }
