/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { parseSheet } from './parse-sheet.js'
import { buildModel } from './model.js'
import { createEvaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareAddresses } from './address.js'
import { SheetError } from './errors.js'

function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  const buf = Buffer.alloc(65536)
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(0, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }
  const mode = args[0]
  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const model = buildModel(sheet)
  const addresses = [...model.keys()].sort(compareAddresses)
  const out = []

  if (mode === 'values') {
    const evaluator = createEvaluator(model)
    for (const addr of addresses) {
      const value = evaluator.getCellValue(addr)
      out.push(`${addr}=${formatValue(value)}\n`)
    }
  } else {
    for (const addr of addresses) {
      const rec = model.get(addr)
      const deps = rec.kind === 'formula' && rec.ast ? collectDeps(rec.ast) : []
      out.push(`${addr}: ${deps.join(' ')}\n`.replace(': \n', ':\n'))
    }
  }

  process.stdout.write(out.join(''))
  process.exit(0)
}

import { createRequire } from 'node:module'
const require = createRequire(import.meta.url)

main()
"}

