import { readFileSync } from 'node:fs'
import { parseSheet } from './parse-sheet.js'
import { buildModel } from './model.js'
import { createEvaluator } from './evaluate.js'
import { collectDeps } from './deps.js'
import { formatValue } from './format.js'
import { compareAddresses } from './address.js'
import { SheetError } from './errors.js'

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch (err) {
    if (err.code === 'EAGAIN') return ''
    throw err
  }
}

function depsLine(addr, deps) {
  return deps.length === 0 ? `${addr}:\n` : `${addr}: ${deps.join(' ')}\n`
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }
  const mode = args[0]
  const input = readStdin()

  let sheet
  try {
    sheet = parseSheet(input)
  } catch (err) {
    if (err instanceof SheetError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const model = buildModel(sheet)
  const addresses = [...model.keys()].sort(compareAddresses)
  const out = []

  if (mode === 'values') {
    const evaluator = createEvaluator(model)
    for (const addr of addresses) {
      out.push(`${addr}=${formatValue(evaluator.getCellValue(addr))}\n`)
    }
  } else {
    for (const addr of addresses) {
      const rec = model.get(addr)
      const deps = rec.kind === 'formula' && rec.ast ? collectDeps(rec.ast) : []
      out.push(depsLine(addr, deps))
    }
  }

  process.stdout.write(out.join(''))
  process.exit(0)
}

main()

